pub fn input_value_to_json(v: &InputValue) -> Result<Value, WireError> {
    match v {
        InputValue::Plane(x) => variant_to("plane", frame_to_json(x)),
        InputValue::Region(x) => variant_to("region", profile_to_json(x)),
        InputValue::Body(x) => variant_to("body", handle_to(x)),
        InputValue::Edge(x) => variant_to("edge", persistent_ref_to_json(x)),
        InputValue::Point(x) => variant_to("point", point_to_json(x)),
        InputValue::Axis(x) => variant_to("axis", axis_to_json(x)),
        InputValue::Tool(x) => variant_to("tool", tool_to_json(x)),
    }
}

pub fn input_value_from_json(v: &Value) -> Result<InputValue, WireError> {
    let (case, payload) = variant(v)?;
    match case {
        "plane" => variant_payload("plane", frame_from_json(payload)).map(InputValue::Plane),
        "region" => variant_payload("region", profile_from_json(payload)).map(InputValue::Region),
        "body" => variant_payload("body", handle_from(payload).map(Body::from_handle))
            .map(InputValue::Body),
        "edge" => variant_payload("edge", persistent_ref_from_json(payload)).map(InputValue::Edge),
        "point" => variant_payload("point", point_from_json(payload)).map(InputValue::Point),
        "axis" => variant_payload("axis", axis_from_json(payload)).map(InputValue::Axis),
        "tool" => variant_payload("tool", tool_from_json(payload)).map(InputValue::Tool),
        other => Err(unknown_case(
            "input-value",
            other,
            &["plane", "region", "body", "edge", "point", "axis", "tool"],
        )),
    }
}

